# coding: utf-8
import pathlib,json
p=pathlib.Path('/tmp/tinct-da-prep-20261104/brothers-karamazov')
en=json.loads((p/'source-brothers-karamazov.json').read_text());da=json.loads((p/'source-brothers-karamazov.da.json').read_text());text=json.loads((p/'candidate-brothers-karamazov-modern-da.json').read_text());eng=json.loads((p/'candidate-brothers-karamazov-modern-en.json').read_text())
en.update(estimatedTime='~28–32 hours',openingText=eng['chapters'][0]['paragraphs'][0],about='The Brothers Karamazov follows a divided family in a Russian provincial town. Fyodor Pavlovich, a neglectful and provocative father, disputes money with his eldest son Dmitri; both pursue Grushenka. Ivan questions religious belief and moral responsibility. Alyosha, a monastery novice, moves between his spiritual teacher Zosima and a family in growing distress. Their conflicts become a murder investigation and a trial.\n\nPublished in 1880, the novel comprises four parts, twelve books and an epilogue. Its author’s preface describes it as the first of two planned novels about Alyosha. The narrative moves between intimate conversations, comic scandal, religious teaching and legal argument. The narrator belongs to the town and sometimes reports rumours rather than established facts.\n\nThe long debates matter because their speakers must also act. Follow what each person believes, what each wants others to believe, and what happens when those convictions meet another person’s suffering. Russian characters may be called by a first name, a patronymic or an affectionate name: Alexey is Alyosha, Dmitri is Mitya, Katerina is Katya and Agrafena is Grushenka.')
da.update(title='Brødrene Karamazov',author='Fjodor Dostojevskij',estimatedTime='~28–32 timer',openingText=text['chapters'][0]['paragraphs'][0],about='Brødrene Karamazov følger en splittet familie i en russisk provinsby. Fjodor Pavlovitj er en forsømmelig far, som gerne provokerer sine omgivelser. Han ligger i strid med sin ældste søn Dmitri om penge, og de gør begge kur til Grusjenka. Ivan undersøger troens og det moralske ansvars grundlag. Aljosja er novice i et kloster og færdes mellem sin åndelige vejleder Zosima og en familie i stadig større krise. Konflikterne fører frem til en mordefterforskning og en retssag.\n\nRomanen udkom i 1880 og består af fire dele, tolv bøger og en epilog. I forordet beskriver forfatteren den som den første af to planlagte romaner om Aljosja. Fortællingen veksler mellem fortrolige samtaler, komiske skandaler, religiøs undervisning og juridiske argumenter. Fortælleren hører selv til i byen og viderebringer undertiden rygter frem for sikre kendsgerninger.\n\nDe lange diskussioner får betydning, fordi personerne også må handle. Læg mærke til, hvad de tror på, hvad de ønsker at få andre til at tro, og hvad der sker, når deres overbevisninger møder et andet menneskes lidelse. De russiske personer kan omtales med fornavn, fadersnavn eller kælenavn: Aleksej er Aljosja, Dmitri er Mitja, Katerina er Katja, og Agrafjena er Grusjenka.')
angles_en=[('Faith and doubt','Ivan challenges attempts to justify the suffering of children. Alyosha listens as a believer who is also disturbed by what he hears. Watch how their affection and disagreement coexist.','I want to follow Ivan’s challenge to faith and Alyosha’s response without assuming either can be reduced to a single doctrine.'),('The Grand Inquisitor','Ivan’s imagined story places Christ in sixteenth-century Seville. The Inquisitor argues that people would trade freedom for bread, certainty and authority. Read it as a story told by one brother to another, as well as a philosophical challenge.','I want to understand how the Grand Inquisitor connects freedom, religious authority and the relationship between the brothers.'),('Desire and responsibility','The brothers are often associated with passion, reason and faith, but each is more complicated than that summary. Follow the distance between a wish, a threat, an action and responsibility for another person.','I want to compare the brothers’ choices and ask how the novel distinguishes legal guilt from moral responsibility.'),('Love in practice','Zosima distinguishes active love from the comforting idea of loving humanity. His teaching invites comparison with Ivan’s objections, but the reader must judge what it can answer.','I want to test Zosima’s teaching against the encounters and choices elsewhere in the novel.')]
angles_da=[('Tro og tvivl','Ivan udfordrer forsøgene på at retfærdiggøre børns lidelse. Aljosja lytter som et troende menneske, der også bliver rystet af det, han hører. Læg mærke til, hvordan deres hengivenhed og uenighed eksisterer side om side.','Jeg vil følge Ivans udfordring af troen og Aljosjas svar uden at reducere nogen af dem til én bestemt lære.'),('Storinkvisitoren','Ivans opdigtede fortælling lader Kristus komme til Sevilla i 1500-tallet. Inkvisitoren hævder, at mennesker vil bytte deres frihed for brød, sikkerhed og autoritet. Læs den både som en filosofisk udfordring og som en historie, den ene bror fortæller den anden.','Jeg vil forstå, hvordan Storinkvisitoren forbinder frihed, religiøs autoritet og forholdet mellem brødrene.'),('Begær og ansvar','Brødrene forbindes ofte med lidenskab, fornuft og tro, men de er hver især mere sammensatte end den opdeling. Følg afstanden mellem et ønske, en trussel, en handling og ansvaret for et andet menneske.','Jeg vil sammenligne brødrenes valg og undersøge, hvordan romanen skelner mellem juridisk skyld og moralsk ansvar.'),('Kærlighed i handling','Zosima skelner mellem kærlighed i handling og den behagelige forestilling om at elske menneskeheden. Hans lære kan læses i forhold til Ivans indvendinger, men læseren må selv vurdere, hvad den kan besvare.','Jeg vil holde Zosimas lære op imod møderne og valgene andre steder i romanen.')]
en['angleCards']=[dict(title=a,text=b,angleObjective=c) for a,b,c in angles_en];da['angleCards']=[dict(title=a,text=b,angleObjective=c) for a,b,c in angles_da]
cast_en=[('Fyodor Pavlovich Karamazov','The father','A wealthy landowner who neglected his three sons. He is provocative, calculating and sometimes unexpectedly vulnerable. His quarrel with Dmitri concerns both money and Grushenka. The accounts of Dmitri’s inheritance are disputed; distinguish his father’s claims from the narrator’s and Dmitri’s.'),('Dmitri Karamazov','The eldest brother','A former officer of twenty-eight, also called Mitya. He is engaged to Katerina Ivanovna and passionately drawn to Grushenka. His extravagant spending, violent anger and longing to act honourably repeatedly collide.'),('Ivan Karamazov','The middle brother','A twenty-three-year-old intellectual who questions the relation between faith, freedom and morality. His arguments draw the attention of both Alyosha and Smerdyakov. His feelings are not always as controlled as his conversation.'),('Alexey Karamazov','The novice','Usually called Alyosha. He is twenty and lives at the monastery under Zosima’s guidance. He listens sympathetically but can also judge, fear and misunderstand. The author’s preface identifies him as the intended hero.'),('Father Zosima','The spiritual elder','A starets: a monk sought out for spiritual guidance. He teaches responsibility for others and love expressed through action. His advice sends Alyosha into the world beyond the monastery.'),('Pavel Smerdyakov','The servant','The cook in Fyodor Pavlovich’s household, raised by Grigory and Marfa after his mother Lizaveta’s death. He has epilepsy and is widely suspected to be Fyodor Pavlovich’s son. He listens closely to Ivan and develops arguments of his own.')]
cast_da=[('Fjodor Pavlovitj Karamazov','Faderen','En velhavende godsejer, der har forsømt sine tre sønner. Han er provokerende, beregnende og undertiden uventet sårbar. Striden med Dmitri drejer sig både om penge og om Grusjenka. Der er uenighed om Dmitris arv; skeln mellem farens påstande, fortællerens oplysninger og Dmitris udlægning.'),('Dmitri Karamazov','Den ældste bror','En tidligere officer på otteogtyve år, også kaldet Mitja. Han er forlovet med Katerina Ivanovna og lidenskabeligt optaget af Grusjenka. Hans ødsle forbrug, voldsomme vrede og længsel efter at handle hæderligt støder igen og igen sammen.'),('Ivan Karamazov','Den mellemste bror','En treogtyveårig intellektuel, der undersøger forholdet mellem tro, frihed og moral. Hans argumenter optager både Aljosja og Smerdjakov. Hans følelser er ikke altid lige så beherskede som hans måde at tale på.'),('Aleksej Karamazov','Novicen','Kaldes som regel Aljosja. Han er tyve år og bor i klosteret under Zosimas vejledning. Han lytter med indlevelse, men kan også dømme, frygte og misforstå. Forfatterens forord udpeger ham som den tilsigtede hovedperson.'),('Fader Zosima','Den åndelige vejleder','En starets: en munk, som mennesker opsøger for at få åndelig vejledning. Han lærer dem at tage ansvar for andre og vise kærlighed gennem handling. Hans råd sender Aljosja ud i verden uden for klosteret.'),('Pavel Smerdjakov','Tjeneren','Kok hos Fjodor Pavlovitj. Grigorij og Marfa har opfostret ham efter hans mor Lizavetas død. Han har epilepsi, og mange mistænker Fjodor Pavlovitj for at være hans far. Han lytter opmærksomt til Ivan og udvikler sine egne argumenter.')]
en['cast']=[dict(name=a,role=b,description=c) for a,b,c in cast_en];da['cast']=[dict(name=a,role=b,description=c) for a,b,c in cast_da]
why_en=[('An argument lived through','The debates about God and suffering do not take place outside the plot. Their speakers are brothers, lovers, servants and teachers with conflicting needs. Consider what an argument reveals about its speaker, and what later choices do to its apparent certainty.'),('What does a family owe?','The father’s neglect makes the question of filial duty difficult. The novel asks what people owe a parent who has failed them, and whether resentment changes that obligation. Financial claims, humiliation, dependence and affection are entangled.'),('Evidence and interpretation','A murder mystery becomes an inquiry into how people construct explanations. Witnesses, gossip and courtroom speeches do not all carry the same authority. The narrator’s qualifications and uncertainties matter, as do the events that resist a convincing story.')]
why_da=[('Argumenter, der bliver levet','Diskussionerne om Gud og lidelse står ikke uden for handlingen. De føres af brødre, elskende, tjenere og vejledere med modstridende behov. Overvej, hvad et argument afslører om den, der fremfører det, og hvad senere valg gør ved dets tilsyneladende sikkerhed.'),('Hvad skylder en familie hinanden?','Farens omsorgssvigt gør spørgsmålet om børnenes pligt vanskeligt. Romanen spørger, hvad man skylder en forælder, der har svigtet, og om bitterhed ændrer den forpligtelse. Pengekrav, ydmygelse, afhængighed og hengivenhed er filtret ind i hinanden.'),('Beviser og fortolkninger','Et mordmysterium bliver til en undersøgelse af, hvordan mennesker skaber forklaringer. Vidner, sladder og taler i retten har ikke samme vægt. Fortællerens forbehold og usikkerhed er vigtige, ligesom de hændelser, der ikke passer ind i en overbevisende historie.')]
en['whyItMatters']=[dict(title=a,body=b) for a,b in why_en];da['whyItMatters']=[dict(title=a,body=b) for a,b in why_da]
